var seed = Math.random() * 1341;
var t;
var num;
var radius;
var sizes = [];

let colors0 = "4596c7-6d8370-e45240-21d3a4-3303f9".split("-").map((a) => "#" + a);
let colors1 = "5d565c-b41a1d-c0dee4-edb136-e07958".split("-").map((a) => "#" + a);
let colors2 = "7382ce-9fb7f4-12177d-9bb5e9-7486af".split("-").map((a) => "#" + a);
let colors3 = "1b1b1b-292929-f3f3f3-222222-ff0000".split("-").map((a) => "#" + a);
let colors4 = "eda492-d59c95-af3918-d9b6b5-853532".split("-").map((a) => "#" + a);
let colors5 = "f86fcd-97d183-240ce8-b0e298-7f37e8".split("-").map((a) => "#" + a);
let colors6 = "2E294E-541388-F1E9DA-FFD400-D90368".split("-").map((a) => "#" + a);
var color_setup;

function setup() {
	randomSeed(seed);
	// pixelDensity(5);
	createCanvas(windowWidth, windowHeight);
	num = random(1000,500);
	radius = max(windowWidth, windowHeight) * 0.3;
	color_setup = random([colors0, colors1, colors2, colors3, colors4, colors5, colors6]);
	for (let a = 0; a < TAU; a += TAU / num) {
		sizes.push(random(0.1, 10))
	}
	background(10);
	t = 0;
}

function draw() {
	randomSeed(seed);
	// background(10);
	background(10, random(55, 30));
  // blendMode(LIGHTEST);
	push();
	translate(width / 2, height / 2);
	rotate(random(TAU) + t);
	for (let i = 0; i < num; i++) {
		let a = (TAU / num) * i + t
		let x = radius * cos(a + t);
		let y = radius * sin(a - t);
		stroke(random(color_setup));
		strokeWeight(sizes[i]);
		let d = random(10, 80);

		drawingContext.shadowColor = str(random(color_setup))+"80";
		drawingContext.shadowOffsetX = 0;
		drawingContext.shadowOffsetY = 0;
		drawingContext.shadowBlur = 10;
		point(x + random(-d, d), y + random(-d, d));
	}
	pop();
	t += 0.003;
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("untitled_20220202", "png");
	}
}

